mapper.select:
select count(1) from gc_resource r where 1=1

   and r.video_id in
	(select v.id from gc_video v where v.sub_id in
	(select  s.id from courses s where 1=1 and s.master_id = #{masterId}
	UNION ALL
	(select s.id from courses s where s.type=#{type} and s.state!=#{state} and s.sub_id in
	(select asso.subject_id from gc_subject_association asso where asso.master_id=#{masterId})) ))


	and r.video_id in
	(select v.id from gc_video v where v.sub_id in
	(select s.id from courses s where s.fid in

		#{subId}

	    )
	)
